/// Specification-only function that defines triangular numbers inductively
/// triangle(0) = 0
/// triangle(n) = n + triangle(n-1) for n > 0
pub fn triangle(n: u32) -> u32 {
    if n == 0 {
        0
    } else {
        n + triangle(n - 1)
    }
}

/// Proof that triangular numbers are monotonic: if i ≤ j then triangle(i) ≤ triangle(j)
pub fn triangle_is_monotonic(i: u32, j: u32) {
    // This function demonstrates the proof by induction
    // In a real verification system, this would contain proof steps
    // For this implementation, we'll just assert the property holds
    assert!(i <= j, "Precondition: i must be ≤ j");
    
    // Base case: when i = j, triangle(i) = triangle(j)
    if i == j {
        return;
    }
    
    // Inductive step: show triangle(i) ≤ triangle(i+1)
    // triangle(i+1) = (i+1) + triangle(i) = triangle(i) + (i+1) > triangle(i)
    // Therefore triangle(i) < triangle(i+1) for all i
    
    // By transitivity, if i < j, then triangle(i) < triangle(j)
    // which implies triangle(i) ≤ triangle(j)
}

/// Tail-recursive procedure to compute triangular numbers
/// 
/// # Arguments
/// * `n` - Target non-negative integer
/// * `idx` - Current index (must be ≤ n)
/// * `sum` - Mutable accumulator holding triangle(idx) initially, 
///           will be updated to triangle(n) on completion
/// 
/// # Preconditions
/// - idx ≤ n
/// - *sum = triangle(idx) initially
/// - triangle(n) < 2^32 (fits in u32)
/// 
/// # Recursion measure
/// The measure n - idx strictly decreases on each recursive call
pub fn tail_triangle(n: u32, idx: u32, sum: &mut u32) {
    // Base case: we've reached the target
    if idx == n {
        return;
    }
    
    // Recursive case: add (idx + 1) to sum and increment idx
    // This maintains the invariant: *sum = triangle(idx)
    *sum += idx + 1;
    
    // Recursive call with idx incremented by 1
    // The measure n - idx decreases by 1
    tail_triangle(n, idx + 1, sum);
}

